def is_valid_stopwatch_time(s):
    import re
    m = re.fullmatch(r'(\d+):(\d{2})', s)
    if not m:
        return False
    minutes, seconds = m.groups()
    if len(minutes) > 1 and minutes[0] == '0':
        return False
    return int(seconds) <= 59

def is_valid_utc_offset(s):
    import re
    m = re.fullmatch(r'([+-])(\d{2}):(\d{2})', s)
    if not m:
        return False
    sign, hh, mm = m.groups()
    if int(mm) > 59:
        return False
    total = int(hh) * 60 + int(mm)
    if sign == '-':
        total = -total
    return -12 * 60 <= total <= 14 * 60

def is_valid_time_range(s):
    import re
    m = re.fullmatch(r'(\d{2}):(\d{2})-(\d{2}):(\d{2})', s)
    if not m:
        return False
    h1, m1, h2, m2 = (int(x) for x in m.groups())
    if not (0 <= h1 <= 23 and 0 <= m1 <= 59 and 0 <= h2 <= 23 and 0 <= m2 <= 59):
        return False
    return h1 * 60 + m1 < h2 * 60 + m2

def is_valid_binary_fraction(s):
    parts = s.split('.')
    if len(parts) != 2:
        return False
    int_part, frac_part = parts
    if not int_part or not frac_part:
        return False
    return all(c in '01' for c in int_part) and all(c in '01' for c in frac_part)

def is_valid_gray_code_step(a, b):
    if len(a) != len(b) or len(a) == 0:
        return False
    if any(c not in '01' for c in a) or any(c not in '01' for c in b):
        return False
    diff = sum(1 for x, y in zip(a, b) if x != y)
    return diff == 1

def is_valid_uuid_v4(s):
    import re
    return bool(re.fullmatch(r'[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}', s))

def is_valid_hex_uuid_plain(s):
    import re
    return bool(re.fullmatch(r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', s))

def is_valid_run_length_encoding(s):
    import re
    if not s:
        return False
    groups = re.findall(r'\d+[A-Za-z]|.', s)
    for g in groups:
        if not re.fullmatch(r'\d+[A-Za-z]', g):
            return False
        count = g[:-1]
        if len(count) > 1 and count[0] == '0':
            return False
        if int(count) == 0:
            return False
    return True

def is_valid_json_number(s):
    import re
    return bool(re.fullmatch(r'-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?', s))

def is_valid_plain_integer_string(s):
    import re
    return bool(re.fullmatch(r'[+-]?(0|[1-9]\d*)', s))

def is_valid_semicolon_list_of_ints(s):
    import re
    if not s:
        return False
    parts = s.split(';')
    return all(re.fullmatch(r'-?(0|[1-9]\d*)', p) for p in parts)

def is_valid_pipe_delimited_record(s, n):
    parts = s.split('|')
    return len(parts) == n and all(p != '' for p in parts)
